Boolean dei_sc_icon_sensor_bypass_full( void )
{            
    dei_sc_info_set( DEI_SC_INFO_SENSOR1_WARNING_BYPASS  , TRUE );  
    dei_sc_info_set( DEI_SC_INFO_SENSOR1_TRIGGER_BYPASS  , TRUE );              
    dei_sc_info_set( DEI_SC_INFO_SENSOR2_WARNING_BYPASS  , TRUE );  
    dei_sc_info_set( DEI_SC_INFO_SENSOR2_TRIGGER_BYPASS  , TRUE );      
    dei_sc_info_set( DEI_SC_INFO_SENSOR3_WARNING_BYPASS  , TRUE );  
    dei_sc_info_set( DEI_SC_INFO_SENSOR3_TRIGGER_BYPASS  , TRUE );  
    
    dei_sc_info_set( DEI_SC_INFO_SENSOR_BYPASS_LEVEL , DEI_BYPASS_FULL ) ;     

    return dei_sc_tx( DEI_SC_ACK_FULL_BYPASS_CONFIRM , DEI_SC_NORMAL_TX , 100 ) ; 
}

